file def transform(grid):
    h, w = len(grid), len(grid[0])
    up = down = 0
    for r in range(h):
        for c in range(w - 2):
            if grid[r][c:c + 3] != [2, 2, 2]:
                continue
            if r > 0 and grid[r - 1][c + 1] == 2:
                up += 1
            if r + 1 < h and grid[r + 1][c + 1] == 2:
                down += 1
    out = [[0] * 6 for _ in range(3)]
    corners = [(0, 0), (0, 2), (2, 0), (2, 2)]
    for i in range(up):
        r, c = corners[i]
        out[r][c] = 3
    for i in range(down):
        r, c = corners[i]
        out[r][c + 3] = 1
    return out
